//! Organizer's sync engine (docs/M5_DESIGN.md §2–§3): keeps local folders
//! and folders of the server's tree the same, both ways, with conflict
//! copies rather than overwrites. No UI: the desktop app
//! (`apps/desktop`) shows its status and drives it.
//!
//! - [`api`]: the API client, generated by progenitor from the backend's
//!   OpenAPI spec at build time (`build.rs`);
//! - [`auth`]: the device login through the system browser;
//! - [`engine`]: the engine itself, with its [`status`];
//! - [`e2e`]: the end-to-end-encrypted folders, decrypted on disk;
//! - [`state`]: what it remembers, per account;
//! - [`on_demand`]: the folders whose files download when opened;
//! - [`remote`] and [`local`]: the two sides; [`names`] and [`ignore`]:
//!   what is mapped and what is left alone.

pub mod api {
    //! Generated by progenitor from the backend's spec (`build.rs`).
    #![allow(clippy::all, missing_docs, unused)]
    include!(concat!(env!("OUT_DIR"), "/client.rs"));
}
pub mod auth;
pub mod e2e;
pub mod engine;
pub mod ignore;
pub mod local;
pub mod names;
pub mod on_demand;
pub mod remote;
pub mod state;
pub mod status;

pub use e2e::PrivateKey;
pub use engine::{Config, Engine};
pub use remote::Role;
pub use state::Mode;
pub use status::{
    Activity, ActivityKind, Encryption, Event, Held, NotSynced, Phase, Status, Waiting,
};

/// What can go wrong.
#[derive(Debug, thiserror::Error)]
pub enum Error {
    /// The server cannot be reached: the changes wait until it can.
    #[error("The server cannot be reached ({0})")]
    Offline(String),
    /// The device's token is no longer valid (revoked, or the user gone).
    #[error("Signed out: sign in again")]
    Unauthorized,
    /// The change feed's cursor is too old (410): list everything again.
    #[error("The change feed's cursor is too old")]
    Gone,
    /// Changed on the server since that version, or the name is taken (409).
    #[error("{0}")]
    Conflict(String),
    /// The drive's storage cannot be used now (503, `code`
    /// `storage_unavailable`): its backend fails, or its private
    /// credentials are locked (docs/M7C_DESIGN.md §4). The reason is fit to
    /// show. Its folders wait; the rest of the pass goes on.
    #[error("{0}")]
    StorageUnavailable(String),
    /// The drive is being moved to other storage: read-only until that is
    /// done (409, `code` `read_only`). What was changed here is sent after.
    #[error("{0}")]
    ReadOnly(String),
    #[error("Not found")]
    NotFound,
    /// Any other answer of the server.
    #[error("The server answered {0}: {1}")]
    Server(u16, String),
    /// A request the engine or the user got wrong.
    #[error("{0}")]
    Invalid(String),
    #[error(transparent)]
    Io(#[from] std::io::Error),
    #[error(transparent)]
    Db(#[from] sqlx::Error),
    #[error(transparent)]
    Migrate(#[from] sqlx::migrate::MigrateError),
}

/// The message of an error body the API sends (`{"error": "...", "code":
/// "..."}`), and its code when it has one.
pub trait ErrorMessage {
    fn message(&self) -> String;
    fn code(&self) -> Option<String> {
        None
    }
}

impl ErrorMessage for api::types::ErrorBody {
    fn message(&self) -> String {
        self.error.clone()
    }
    fn code(&self) -> Option<String> {
        self.code.clone()
    }
}

impl ErrorMessage for () {
    fn message(&self) -> String {
        String::new()
    }
}

/// The `code` of a 503 whose drive's storage cannot be used now.
pub const STORAGE_UNAVAILABLE: &str = "storage_unavailable";

/// The `code` of a 409 refusing a write to a drive being moved to other
/// storage (read-only until that is done): told from a version conflict,
/// which must not become a conflict copy here; the drive's `moving_to` is
/// what the engine looks at first.
pub const READ_ONLY: &str = "read_only";

/// The `code` of a 502 when the other server a drive (or an encrypted
/// folder's keys) comes from does not answer.
pub const REMOTE_UNREACHABLE: &str = "remote_unreachable";

impl Error {
    /// The error of a generated call.
    pub fn from_api<E: ErrorMessage + std::fmt::Debug>(error: progenitor_client::Error<E>) -> Self {
        use progenitor_client::Error as E;
        match error {
            E::ErrorResponse(response) => Self::from_answer(
                response.status().as_u16(),
                response.message(),
                response.code().as_deref(),
            ),
            E::CommunicationError(e) | E::ResponseBodyError(e) => Self::from_reqwest(e),
            E::UnexpectedResponse(response) => {
                Self::from_status(response.status().as_u16(), String::new())
            }
            other => Error::Invalid(other.to_string()),
        }
    }

    /// A request that got no answer is the server being away.
    pub fn from_reqwest(error: reqwest::Error) -> Self {
        match error.status() {
            Some(status) => Self::from_status(status.as_u16(), error.to_string()),
            None => Error::Offline(error.to_string()),
        }
    }

    pub fn from_status(status: u16, message: String) -> Self {
        Self::from_answer(status, message, None)
    }

    /// An answer that is not a success: its status, its message, and the
    /// `code` of its body when it has one.
    pub fn from_answer(status: u16, message: String, code: Option<&str>) -> Self {
        match status {
            401 => Error::Unauthorized,
            404 => Error::NotFound,
            409 if code == Some(READ_ONLY) => Error::ReadOnly(message),
            409 => Error::Conflict(message),
            503 if code == Some(STORAGE_UNAVAILABLE) => Error::StorageUnavailable(message),
            410 => Error::Gone,
            // A drive shared from another server whose server does not
            // answer (docs/M7E_DESIGN.md §10): its folders wait, as for
            // storage that is down; ours is there.
            502 if code == Some(REMOTE_UNREACHABLE) => {
                Error::StorageUnavailable("The owner's server is not reachable".into())
            }
            // A proxy in front of a server that is down.
            502..=504 => Error::Offline(format!("{status}")),
            _ => Error::Server(status, message),
        }
    }

    /// Whether the server is away: the work waits, nothing is wrong.
    pub fn is_offline(&self) -> bool {
        matches!(self, Error::Offline(_))
    }

    /// Whether the change waits for the server, or for its drive's storage
    /// (unavailable, or being moved): sent again later, nothing is wrong
    /// with it.
    pub fn waits(&self) -> bool {
        matches!(
            self,
            Error::Offline(_) | Error::StorageUnavailable(_) | Error::ReadOnly(_)
        )
    }
}

/// Install ring as the process' TLS provider: reqwest is built without one
/// (`rustls-no-provider`, as in the backend). Safe to call more than once.
pub fn install_tls_provider() {
    use std::sync::Once;
    static INSTALL: Once = Once::new();
    INSTALL.call_once(|| {
        rustls::crypto::ring::default_provider()
            .install_default()
            .ok();
    });
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn an_owners_server_that_does_not_answer_makes_its_folders_wait() {
        let e = Error::from_answer(502, "no answer".into(), Some(REMOTE_UNREACHABLE));
        assert_eq!(e.to_string(), "The owner's server is not reachable");
        assert!(e.waits() && !e.is_offline());
        // Any other 502 is a proxy in front of a server that is down.
        assert!(Error::from_answer(502, String::new(), None).is_offline());
    }
}
